package entities;import java.time.LocalDateTime;import java.util.ArrayList;import java.util.List;public class Post {    private LocalDateTime moment;    private String tittle;    private String content;    private Integer likes;    private List<Comment> comments = new ArrayList<>();    public Post() {    }    public Post(LocalDateTime moment, String tittle, String content, Integer likes) {        this.moment = moment;        this.tittle = tittle;        this.content = content;        this.likes = likes;    }    public LocalDateTime getMoment() {        return moment;    }    public void setMoment(LocalDateTime moment) {        this.moment = moment;    }    public String getTittle() {        return tittle;    }    public void setTittle(String tittle) {        this.tittle = tittle;    }    public String getContent() {        return content;    }    public void setContent(String content) {        this.content = content;    }    public Integer getLikes() {        return likes;    }    public void setLikes(Integer likes) {        this.likes = likes;    }    public List<Comment> getComments() {        return comments;    }    public void addComents(Comment comment) {        comments.add(comment);    }    public void removeComents(Comment comment) {        comments.remove(comment);    }}